def build_recipes(lang):
    en=lang=="en"; title="Recipes | ami anytime" if en else "Recetas | ami anytime"; intro="Six simple recipes made with ami products and everyday staples." if en else "Seis recetas sencillas con productos ami e ingredientes de todos los días."
    cards="".join(recipe_card(r["image"],r[lang][0],r["time"],r["uses_en" if en else "uses_es"],r["id"],lang) for r in RECIPES)
    articles=[]
    for r in RECIPES:
        name,ingredients,steps=r[lang]; uses=r["uses_en" if en else "uses_es"]
        width,height=IMAGE_SIZES[r["image"]]
        articles.append(f'''<article class="recipe-article" id="{r['id']}"><div class="recipe-media{' packshot' if r.get('packshot') else ''}"><img src="{asset('img/'+r['image'],lang)}" width="{width}" height="{height}" alt="{esc(name)}" loading="lazy"></div><div class="recipe-body"><span class="eyebrow">{('Prep' if en else 'Preparación')}: {r['time']} · {('Serves 4' if en else 'Rinde 4 porciones')}</span><h2>{name}</h2><h3>{'ami products in this recipe' if en else 'Productos ami en esta receta'}</h3><div class="uses">{"".join(f'<span>{esc(x)}</span>' for x in uses)}</div><h3>{'Ingredients' if en else 'Ingredientes'}</h3><ul>{"".join(f'<li>{esc(x)}</li>' for x in ingredients)}</ul><h3>{'Method' if en else 'Preparación'}</h3><ol>{"".join(f'<li>{esc(x)}</li>' for x in steps)}</ol></div></article>''')
    main=f'''<main id="main" class="page-shell">{page_hero(lang,'Recipes' if en else 'Recetas','Easy meals from the pantry' if en else 'Comidas fáciles con lo que hay en la despensa',intro,'Recipes' if en else 'Recetas')}<section class="recipe-index"><div class="recipe-grid">{cards}</div></section>{''.join(articles)}<section class="retailer-panel"><div><span class="eyebrow light">ami anytime</span><h2>{'Find the products for your next meal' if en else 'Encuentra los productos para tu próxima comida'}</h2><p>{'Browse the launch range by category and pack size.' if en else 'Explora el surtido de lanzamiento por categoría y tamaño.'}</p></div><a class="button light" href="{href('products',lang)}">{'Browse products' if en else 'Ver productos'} {ARROW}</a></section></main>'''
    schema={"@context":"https://schema.org","@graph":[{"@type":"Recipe","name":r[lang][0],"image":f"{SITE}/img/{r['image']}","prepTime":"PT"+r["time"].replace(" min","M"),"recipeYield":"4 servings" if en else "4 porciones"} for r in RECIPES]}
    return frame("recipes",lang,title,intro,main,schema)

def build_pdp(lang):
    en=lang=="en"; name="Tomato Paste" if en else "Pasta de tomate"; lead="Concentrated tomato for sauces, rice, soups and stews." if en else "Tomate concentrado para salsas, arroz, sopas y guisos."
    facts=[("What it is","Concentrated tomato paste for everyday cooking."),("How to use it","Add it to sofrito, sauces, rice, soups and stews for deeper tomato flavor."),("Package information","See the package for ingredients, nutrition and storage instructions.")] if en else [("Qué es","Pasta de tomate concentrada para cocinar todos los días."),("Cómo usarla","Agrégala al sofrito, las salsas, el arroz, las sopas y los guisos para intensificar el sabor a tomate."),("Información del empaque","Consulta en el empaque los ingredientes, la información nutricional y las instrucciones de conservación.")]
    main=f'''<main id="main" class="page-shell"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="{href('home',lang)}">{'Home' if en else 'Inicio'}</a><span>/</span><a href="{href('products',lang)}">{'Products' if en else 'Productos'}</a><span>/</span><span>{name}</span></nav><section class="pdp"><div class="pdp-stage"><img src="{asset('img/tomato-paste.webp',lang)}" width="860" height="860" alt="ami {name}, 400 g"></div><div class="pdp-copy"><span class="eyebrow">{'Tomato' if en else 'Tomate'}</span><h1>{name}</h1><p class="pdp-lead">{lead}</p><span class="pack-size">400 g</span><ul class="fact-list">{"".join(f'<li><strong>{h}</strong><span>{p}</span></li>' for h,p in facts)}</ul><div class="actions"><a class="button navy" href="{href('where-to-buy',lang)}">{'Where to buy' if en else 'Dónde comprar'}</a><a class="button ghost" href="{href('contact',lang)}">{'Request product information' if en else 'Solicitar información del producto'}</a></div></div></section><section class="recipe-callout"><img src="{asset('img/new-life-cooking-582.webp',lang)}" width="582" height="619" alt="{'Pantry tomato pasta' if en else 'Pasta de tomate de la despensa'}" loading="lazy"><div><span class="eyebrow">{'Cook with ami' if en else 'Cocinar con ami'}</span><h2>{'Pantry tomato pasta' if en else 'Pasta de tomate de la despensa'}</h2><p>{'A simple weeknight meal built around tomatoes, tuna and pantry staples.' if en else 'Una comida sencilla para la semana con tomates, atún y productos de la despensa.'}</p></div><a class="button navy" href="{href('recipes',lang)}#tomato-pasta">{'View recipe' if en else 'Ver receta'}</a></section></main>'''
    schema={"@context":"https://schema.org","@type":"Product","name":f"ami {name}","image":f"{SITE}/img/tomato-paste.webp","description":lead,"brand":{"@type":"Brand","name":"ami anytime"},"size":"400 g"}
    return frame("product-tomato-paste",lang,f"{name} | ami anytime",lead,main,schema)

def build_about(lang):
    en=lang=="en"; intro="ami anytime™ is the own-brand program of American Foods International: one recognizable identity for familiar everyday products, shaped market by market and category by category." if en else "ami anytime™ es el programa de marca propia de American Foods International: una identidad reconocible para productos cotidianos conocidos, desarrollada mercado por mercado y categoría por categoría."
    values=[("Easy to recognize","A consistent navy band connects the range across categories."),("Practical by design","Familiar foods and clear pack information support everyday choices."),("Built market by market","Products, packs and labels are defined for each market.")] if en else [("Fácil de reconocer","Una banda azul consistente conecta el surtido entre categorías."),("Práctica por diseño","Alimentos conocidos e información clara en el empaque apoyan las decisiones diarias."),("Desarrollada mercado por mercado","Los productos, empaques y etiquetas se definen para cada mercado.")]
    chapters=(("01","Begin with the pantry","Start with products people know, buy and use often."),("02","Earn recognition","Let one clear brand system build familiarity across the aisle."),("03","Expand with discipline","Add markets and categories when product readiness, demand and partner economics support them.")) if en else (("01","Comenzar por la despensa","Empezar con productos que las personas conocen, compran y usan con frecuencia."),("02","Ganar reconocimiento","Permitir que un sistema de marca claro cree familiaridad en todo el pasillo."),("03","Crecer con disciplina","Agregar mercados y categorías cuando la preparación, la demanda y la viabilidad lo respalden."))
    support="Keep the package and contact the store where you bought it or write to us. Include the product name, lot code and best-before date so we can review it." if en else "Conserva el empaque y comunícate con la tienda donde lo compraste o escríbenos. Incluye el nombre del producto, el código de lote y la fecha de consumo preferente para que podamos revisarlo."
    main=f'''<main id="main" class="page-shell">{page_hero(lang,'Our brand' if en else 'Nuestra marca','A friend for everyday life' if en else 'Una marca cercana para cada día',intro,'Our brand' if en else 'Nuestra marca')}<section class="split-section"><div class="split-copy"><span class="eyebrow">ami anytime</span><h2>{'One clear brand, created to grow' if en else 'Una marca clara, creada para crecer'}</h2><p>{'ami began with a simple idea: everyday groceries should be easier to recognize, choose and use. The name evokes a friend—familiar, useful and ready for the moments that make up real life.' if en else 'ami nació de una idea sencilla: los productos cotidianos deberían ser más fáciles de reconocer, elegir y usar. Su nombre evoca a un amigo: cercano, útil y presente en los momentos de la vida real.'}</p><div class="value-list">{"".join(f'<div><strong>{h}</strong><span>{p}</span></div>' for h,p in values)}</div></div><div class="split-media"><img src="{asset('img/new-life-kid.webp',lang)}" width="1439" height="1071" alt="{'ami in an everyday family moment' if en else 'ami en un momento familiar cotidiano'}" loading="lazy"></div></section><section class="story-chapters" data-reveal><div class="section-heading"><div><span class="eyebrow">{'How the story grows' if en else 'Cómo crece la historia'}</span><h2>{'Market by market. Category by category.' if en else 'Mercado por mercado. Categoría por categoría.'}</h2></div></div><div class="chapter-grid">{"".join(f'<article><span>{n}</span><h3>{h}</h3><p>{p}</p></article>' for n,h,p in chapters)}</div></section><section class="ambition-band" data-reveal><span class="eyebrow light">{'The horizon' if en else 'El horizonte'}</span><h2>{'Our ambition is to build the largest imported everyday brand across the Americas.' if en else 'Nuestra ambición es construir la marca importada de productos cotidianos más grande de las Américas.'}</h2><p>{'That is the destination we are building toward—not a claim about our position today. Progress will be earned through active markets, reliable products, real availability and households that choose ami again.' if en else 'Ese es el destino que estamos construyendo, no una afirmación sobre nuestra posición actual. El progreso se ganará con mercados activos, productos confiables, disponibilidad real y hogares que vuelvan a elegir ami.'}</p></section><section class="identity-panel"><div><span class="eyebrow">{'Recognizing ami' if en else 'Cómo reconocer ami'}</span><h2>{'Find the navy band' if en else 'Busca la banda azul'}</h2><p>{'Look for the navy ami band and green line. Aisle colors help distinguish beans and vegetables, tomato products, corn, fruit and products of the sea at a glance.' if en else 'Busca la banda azul de ami y la línea verde. Los colores por pasillo ayudan a distinguir de inmediato los frijoles y vegetales, productos de tomate, maíz, frutas y productos del mar.'}</p></div><div class="identity-product"><img src="{asset('img/new-whole-peeled-tomatoes.webp',lang)}" width="860" height="860" alt="ami {'Whole Peeled Tomatoes' if en else 'Tomates enteros pelados'}"></div></section>{afi_panel(lang)}<section class="empty-state" id="product-support"><span class="eyebrow light">{'Product support' if en else 'Ayuda con un producto'}</span><h2>{'Questions about a product?' if en else '¿Tienes alguna pregunta sobre un producto?'}</h2><p>{support}</p><div class="actions"><a class="button light" href="{href('contact',lang)}">{'Contact us' if en else 'Contáctanos'}</a></div></section></main>'''
    return frame("about",lang,"Our brand | ami anytime" if en else "Nuestra marca | ami anytime",intro,main)

def build_where(lang):
    en=lang=="en"; intro="Explore the markets in the ami growth roadmap. As partners and stores are confirmed for publication, this map will become a local guide to where ami can be found." if en else "Explora los mercados del plan de crecimiento de ami. A medida que socios y tiendas sean confirmados para publicación, este mapa se convertirá en una guía local para encontrar ami."
    markers=[]; cards=[]
    for i,(slug,en_name,es_name,x,y) in enumerate(MARKETS,1):
        name=en_name if en else es_name
        status="Growth roadmap · no launch announced" if en else "Plan de crecimiento · lanzamiento no anunciado"
        body="The future country-partner profile and confirmed store information will be published here when approved." if en else "El perfil del futuro socio en el país y la información de tiendas confirmadas se publicarán aquí cuando sean aprobados."
        markers.append(f'<button class="market-marker" type="button" style="--x:{x}%;--y:{y}%" data-market="{slug}" data-name="{esc(name)}" data-status="{esc(status)}" data-body="{esc(body)}" aria-label="{esc(name+": "+status)}" aria-pressed="{"true" if slug=="panama" else "false"}"><span>{i}</span></button>')
        cards.append(f'<article class="market-card" id="market-{slug}" data-market-card="{slug}"><span class="market-index">{i:02d}</span><div><h3>{name}</h3><strong>{status}</strong><p>{body}</p></div></article>')
    milestones=(("01","Explore","See the markets under consideration."),("02","Meet the partner","Country profiles will identify the authorized local partner after confirmation."),("03","Find a store","Verified retailers and locations will be added as availability is approved.")) if en else (("01","Explora","Conoce los mercados que estamos evaluando."),("02","Conoce al socio","Los perfiles por país identificarán al socio local autorizado después de su confirmación."),("03","Encuentra una tienda","Las cadenas y ubicaciones verificadas se agregarán cuando se apruebe su publicación."))
    main=f'''<main id="main" class="page-shell">{page_hero(lang,'Where to buy' if en else 'Dónde comprar','The ami map starts here' if en else 'El mapa de ami comienza aquí',intro,'Where to buy' if en else 'Dónde comprar')}<section class="market-explorer" data-reveal><div class="market-intro"><div><span class="eyebrow">{'The Americas' if en else 'Las Américas'}</span><h2>{'A brand being built across markets' if en else 'Una marca que se construye entre mercados'}</h2></div><p id="map-note">{'Highlighted markets show future partnership interest, not current product or store availability.' if en else 'Los mercados destacados muestran interés futuro de asociación, no disponibilidad actual de productos o tiendas.'}</p></div><a class="skip-map" href="#market-list">{'Skip map and view the market list' if en else 'Saltar el mapa y ver la lista de mercados'}</a><div class="market-map-layout"><div class="market-map-frame" role="group" aria-label="{'Interactive growth roadmap of the Americas' if en else 'Plan interactivo de crecimiento en las Américas'}" aria-describedby="map-note"><img src="{asset('img/america-map.svg',lang)}" width="389" height="377" alt="" loading="eager">{"".join(markers)}</div><aside class="market-feature" aria-live="polite"><span class="market-index">02</span><span class="status-chip">{'Growth roadmap' if en else 'Plan de crecimiento'}</span><h3>Panamá</h3><strong>{'No launch announced' if en else 'Lanzamiento no anunciado'}</strong><p>{'The future country-partner profile and confirmed store information will be published here when approved.' if en else 'El perfil del futuro socio en el país y la información de tiendas confirmadas se publicarán aquí cuando sean aprobados.'}</p><a class="text-link" href="#market-panama">{'View market card' if en else 'Ver ficha del mercado'} {ARROW}</a></aside></div><div class="market-list" id="market-list">{"".join(cards)}</div></section><section class="availability-path" data-reveal><div class="section-heading"><div><span class="eyebrow">{'How this page will grow' if en else 'Cómo crecerá esta página'}</span><h2>{'From roadmap to shelf' if en else 'Del plan al anaquel'}</h2></div></div><div class="chapter-grid">{"".join(f'<article><span>{n}</span><h3>{h}</h3><p>{p}</p></article>' for n,h,p in milestones)}</div></section><section class="retailer-panel"><div><span class="eyebrow light">{'Retailers and distributors' if en else 'Cadenas y distribuidores'}</span><h2>{'Want to build ami in your market?' if en else '¿Quieres desarrollar ami en tu mercado?'}</h2><p>{'Explore the country-partner model and tell us about your reach, channels and categories.' if en else 'Conoce el modelo de socios por país y cuéntanos sobre tu alcance, canales y categorías.'}</p></div><a class="button light" href="{href('partners',lang)}">{'For partners' if en else 'Para socios'} {ARROW}</a></section></main>'''
    return frame("where-to-buy",lang,"Where to buy | ami anytime" if en else "Dónde comprar | ami anytime",intro,main)

def build_partners(lang):
    en=lang=="en"; intro="ami anytime™ is an American Foods International consumer brand designed to grow with selected retailers and distributors—one market, one disciplined assortment and one category at a time." if en else "ami anytime™ es una marca de consumo de American Foods International diseñada para crecer con cadenas y distribuidores seleccionados: un mercado, un surtido disciplinado y una categoría a la vez."
    retailer_points=(("Differentiate the value tier","Create a recognizable proposition competitors cannot copy product for product."),("Build loyalty across the basket","Let trust earned in one category support discovery in the next."),("Shape value locally","Set product, pack, shelf role and target price position market by market."),("Expand on proof","Add categories when readiness, demand and economics support them.")) if en else (("Diferenciar el segmento de valor","Crear una propuesta reconocible que la competencia no pueda replicar producto por producto."),("Construir lealtad en la canasta","Permitir que la confianza ganada en una categoría impulse la siguiente."),("Definir el valor localmente","Establecer producto, tamaño, rol y posición de precio para cada mercado."),("Crecer con evidencia","Agregar categorías cuando la preparación, la demanda y la viabilidad lo respalden."))
    distributor_points=(("One label across the route","Build recognition from modern retail to neighborhood trade across multiple categories."),("A portfolio that can keep growing","Begin with everyday foods, then add approved food, beverage, household and personal-care categories."),("International identity, local relevance","Bring a consistent bilingual brand while adapting assortment and value position to the country."),("A fair way to compete","Aim for market-relevant pricing that can stand beside local products without making unsupported lowest-price promises.")) if en else (("Una marca para toda la ruta","Construir reconocimiento desde las cadenas hasta el comercio de barrio, en múltiples categorías."),("Un portafolio que puede seguir creciendo","Comenzar con alimentos cotidianos y luego sumar categorías aprobadas de alimentos, bebidas, hogar y cuidado personal."),("Identidad internacional, relevancia local","Llevar una marca bilingüe consistente adaptando el surtido y la posición de valor al país."),("Una forma justa de competir","Buscar precios adecuados para el mercado que puedan competir con productos locales sin promesas no sustentadas de precio mínimo."))
    steps=(("1","Define the market","Align territory, channels, local requirements and commercial fit."),("2","Build the launch range","Choose approved products, packs, specifications and a clear value architecture."),("3","Prove and expand","Measure availability, velocity, replenishment and shopper response before the next wave.")) if en else (("1","Definir el mercado","Alinear territorio, canales, requisitos locales y viabilidad comercial."),("2","Construir el surtido inicial","Elegir productos, tamaños, especificaciones y una arquitectura de valor claros."),("3","Probar y expandir","Medir disponibilidad, rotación, reposición y respuesta del consumidor antes de la siguiente ola."))
    main=f'''<main id="main" class="page-shell">{page_hero(lang,'For partners' if en else 'Para socios','One everyday brand. A countrywide growth platform.' if en else 'Una marca cotidiana. Una plataforma de crecimiento nacional.',intro,'For partners' if en else 'Para socios')}<section class="market-evidence" data-reveal><div class="evidence-lead"><span class="eyebrow light">{'The global shift' if en else 'El cambio global'}</span><h2>{'Private label has become a loyalty strategy.' if en else 'La marca propia se ha convertido en una estrategia de lealtad.'}</h2><p>{'Consumers increasingly see private labels as credible choices, not compromises. The opportunity is bigger than a lower ticket: a strong controlled brand can create differentiation, recognition and value that belongs to the partnership.' if en else 'Cada vez más consumidores ven las marcas propias como opciones creíbles, no como un sacrificio. La oportunidad va más allá de un precio menor: una marca propia sólida puede crear diferenciación, reconocimiento y valor que pertenecen a la alianza.'}</p></div><div class="evidence-grid"><div><strong>4.3%</strong><span>{'global year-over-year private-label sales growth' if en else 'crecimiento interanual global de ventas de marca propia'}</span></div><div><strong>69%</strong><span>{'see private label as good value' if en else 'considera que la marca propia ofrece buen valor'}</span></div><div><strong>60%</strong><span>{'would buy more with greater variety' if en else 'compraría más si hubiera mayor variedad'}</span></div></div><p class="source-note">{'Source: NIQ, 2025 Global Outlook, survey of 17,000+ consumers in 25 countries. Market context—not ami sales or market share.' if en else 'Fuente: NIQ, Perspectiva Global 2025, encuesta a más de 17,000 consumidores en 25 países. Contexto de mercado; no representa ventas ni participación de ami.'} <a href="https://nielseniq.com/global/en/news-center/2025/niqs-global-report-reveals-challenges-and-opportunities-for-private-label-and-branded-product-growth/">{'Read the research' if en else 'Ver la investigación'}</a>.</p></section><section class="role-chooser" data-reveal><div class="section-heading"><div><span class="eyebrow">{'Choose your path' if en else 'Elige tu ruta'}</span><h2>{'One brand. Two ways to build a market.' if en else 'Una marca. Dos formas de desarrollar un mercado.'}</h2></div></div><div class="role-grid"><a class="role-card retailer" href="#retailers"><span>01</span><h3>{'For retailers' if en else 'Para cadenas'}</h3><p>{'Build a controlled or exclusively represented value brand that can grow across the basket.' if en else 'Desarrolla una marca de valor propia o de representación exclusiva que pueda crecer en toda la canasta.'}</p>{ARROW}</a><a class="role-card distributor" href="#distributors"><span>02</span><h3>{'For distributors' if en else 'Para distribuidores'}</h3><p>{'Use one international label to build reach across channels, territories and categories.' if en else 'Usa una marca internacional para ampliar el alcance entre canales, territorios y categorías.'}</p>{ARROW}</a></div></section><section class="partner-story" id="retailers"><div class="partner-heading"><span class="eyebrow">{'For retailers' if en else 'Para cadenas'}</span><h2>{'A value brand your market can make its own.' if en else 'Una marca de valor que tu mercado puede hacer suya.'}</h2><p>{'National brands are broadly available. A controlled brand gives a retailer a more distinctive proposition: a coherent identity, an assortment shaped around local shoppers and, where agreed in writing, protected territory or category rights.' if en else 'Las marcas nacionales están disponibles para todos. Una marca propia ofrece a la cadena una propuesta más distintiva: identidad coherente, surtido pensado para el consumidor local y, cuando exista un acuerdo escrito, derechos protegidos por territorio o categoría.'}</p></div><div class="partner-pillars">{"".join(f'<article><h3>{h}</h3><p>{p}</p></article>' for h,p in retailer_points)}</div><a class="button navy" href="{href('contact',lang)}#retail-inquiry">{'Discuss a retail program' if en else 'Conversemos sobre un programa para cadenas'} {ARROW}</a></section><section class="partner-story distributor-story" id="distributors"><div class="partner-heading"><span class="eyebrow light">{'For distributors' if en else 'Para distribuidores'}</span><h2>{'Reach every corner with a brand built to travel.' if en else 'Llega a cada rincón con una marca creada para avanzar.'}</h2><p>{'In selected countries, ami will grow through qualified distributors with the relationships and operating reach to build a national brand. The goal is not a one-category listing—it is a platform that can expand across dozens of everyday categories over time.' if en else 'En países seleccionados, ami crecerá con distribuidores calificados que tengan las relaciones y el alcance operativo para desarrollar una marca nacional. La meta no es listar una sola categoría, sino crear una plataforma que pueda crecer con el tiempo en decenas de categorías cotidianas.'}</p></div><div class="partner-pillars">{"".join(f'<article><h3>{h}</h3><p>{p}</p></article>' for h,p in distributor_points)}</div><a class="button light" href="{href('contact',lang)}#distribution-inquiry">{'Discuss country distribution' if en else 'Conversemos sobre distribución en tu país'} {ARROW}</a></section><section class="partner-process" data-reveal><div class="section-heading"><div><span class="eyebrow">{'The operating model' if en else 'El modelo operativo'}</span><h2>{'Depth before breadth.' if en else 'Profundidad antes que amplitud.'}</h2><p>{'ami is not designed to launch everything everywhere at once. Scale is earned through a focused start, reliable execution and measured expansion.' if en else 'ami no fue diseñada para lanzar todo, en todas partes, al mismo tiempo. La escala se gana con un inicio enfocado, ejecución confiable y expansión medida.'}</p></div></div><div class="process-grid">{"".join(f'<article><span>{n}</span><h3>{h}</h3><p>{p}</p></article>' for n,h,p in steps)}</div><div class="roadmap-ribbon"><strong>{'Today' if en else 'Hoy'}</strong><span>{'Pantry, sauces, noodles and fruit drinks' if en else 'Despensa, salsas, fideos y bebidas de fruta'}</span><i></i><strong>{'Roadmap' if en else 'Plan'}</strong><span>{'Additional food, beverage, dairy, frozen, household and personal-care categories—subject to approval.' if en else 'Categorías adicionales de alimentos, bebidas, lácteos, congelados, hogar y cuidado personal, sujetas a aprobación.'}</span></div></section>{afi_panel(lang)}<section class="retailer-panel"><div><span class="eyebrow light">{'Start a conversation' if en else 'Inicia una conversación'}</span><h2>{'Tell us how your market moves.' if en else 'Cuéntanos cómo se mueve tu mercado.'}</h2><p>{'Share your country, channels, reach, import experience and categories of interest. Territory scope and any exclusivity are defined only by written agreement.' if en else 'Comparte tu país, canales, alcance, experiencia de importación y categorías de interés. El territorio y cualquier exclusividad se definen únicamente mediante acuerdo escrito.'}</p></div><a class="button light" href="{href('contact',lang)}">{'Contact the ami team' if en else 'Contactar al equipo de ami'} {ARROW}</a></section></main>'''
    return frame("partners",lang,"For retailers and distributors | ami anytime" if en else "Para cadenas y distribuidores | ami anytime",intro,main)

def build_contact(lang):
    en=lang=="en"; intro="Choose a topic so your message reaches the right team." if en else "Elige un tema para que tu mensaje llegue al equipo indicado."
    topics=[("product-question","Product question","Include the product name, lot code and best-before date.","ami product question"),("retail-inquiry","Retail inquiry","Tell us about your company, market and categories.","ami retailer inquiry"),("distribution-inquiry","Distribution partnership","Share your country, channel coverage and import experience.","ami distribution partnership"),("supplier-proposal","Supplier proposal","Share the company and products you represent.","ami supplier proposal"),("media-other","Media or other","Send the context needed to route your message.","ami general inquiry")] if en else [("product-question","Consulta sobre un producto","Incluye el nombre del producto, el código de lote y la fecha de consumo preferente.","Consulta sobre un producto ami"),("retail-inquiry","Consulta para cadenas","Cuéntanos sobre tu empresa, mercado y categorías.","Consulta para cadenas ami"),("distribution-inquiry","Alianza de distribución","Comparte tu país, cobertura de canales y experiencia de importación.","Alianza de distribución ami"),("supplier-proposal","Propuesta de proveedor","Comparte la empresa y los productos que representas.","Propuesta de proveedor ami"),("media-other","Prensa u otro","Envía el contexto necesario para dirigir tu mensaje.","Consulta general ami")]
    cards="".join(f'<article class="route-card" id="{slug}"><span class="route-number">{i}</span><h2>{h}</h2><p>{p}</p><a class="text-link" href="mailto:info@afoodsinc.com?subject={s.replace(" ","%20")}">{"Write to us" if en else "Escríbenos"} {ARROW}</a></article>' for i,(slug,h,p,s) in enumerate(topics,1))
    main=f'''<main id="main" class="page-shell">{page_hero(lang,'Contact' if en else 'Contacto','How can we help?' if en else '¿Cómo podemos ayudarte?',intro,'Contact' if en else 'Contacto')}<section class="route-grid contact-routes">{cards}</section><section class="office-grid"><article class="office"><h2>{'United States office and warehouse' if en else 'Oficina y bodega en Estados Unidos'}</h2><address>2300 NW 92nd Ave<br>Doral, FL 33172, USA<br><a class="text-link" href="tel:+18778947675">+1 877 894 7675</a></address></article><article class="office"><h2>{'Panama office' if en else 'Oficina de Panamá'}</h2><address>PH Plaza del Este, Torre A, Piso 13<br>Costa del Este, Panamá<br><a class="text-link" href="tel:+5073107576">+507 310 7576</a></address></article></section></main>'''
    return frame("contact",lang,"Contact | ami anytime" if en else "Contacto | ami anytime",intro,main)

def build_404():
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>Page not found | ami anytime</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700;800&amp;family=Nunito:wght@800;900&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="site.css"></head><body><a class="skip-link" href="#main">Skip to content</a><main id="main" class="page-shell"><section class="page-hero error-hero"><span class="eyebrow">Wrong aisle? · ¿Pasillo equivocado?</span><h1>404</h1></section><section class="error-panels"><article class="route-card"><h2>This page isn’t here.</h2><p>We couldn’t find that page. Choose where to go next.</p><div class="actions"><a class="button navy" href="index.html">Home</a><a class="button ghost" href="products.html">Products</a><a class="button ghost" href="recipes.html">Recipes</a></div></article><article class="route-card" lang="es"><h2>Esta página no está aquí.</h2><p>No encontramos esa página. Elige cómo continuar.</p><div class="actions"><a class="button navy" href="es/index.html">Inicio</a><a class="button ghost" href="es/products.html">Productos</a><a class="button ghost" href="es/recipes.html">Recetas</a></div></article></section></main></body></html>'''

def write(slug,lang,content):
    target=ROOT/page_path(slug,lang); target.parent.mkdir(parents=True,exist_ok=True); target.write_text(content.strip()+"\n",encoding="utf-8")

def main():
    parser=argparse.ArgumentParser(); parser.add_argument("--home-only",action="store_true"); args=parser.parse_args()
    builders={"home":build_home}
    if not args.home_only:
        builders.update({"products":build_products,"product-tomato-paste":build_pdp,"recipes":build_recipes,"about":build_about,"where-to-buy":build_where,"partners":build_partners,"contact":build_contact})
    for lang in ("en","es"):
        for slug,builder in builders.items(): write(slug,lang,builder(lang))
    if not args.home_only:
        (ROOT/"404.html").write_text(build_404().strip()+"\n",encoding="utf-8")

if __name__ == "__main__": main()
